AMENDMENT_D_SHA256="c419cbdc0bc26670d5c18b37f183a9cd3481b00680f0b10d3176e482ef1d5be4"

def _sha(value: Any) -> str:
    return hashlib.sha256(canonical_json(value).encode()).hexdigest()

def _hash64(value: str, code: str) -> str:
    if len(value) != 64 or any(ch not in "0123456789abcdef" for ch in value):
        raise FailClosed(code)
    return value

def _amendment_d_sha256() -> str:
    configured=os.environ.get("P5_AMENDMENT_D_SHA256",AMENDMENT_D_SHA256)
    if configured!=AMENDMENT_D_SHA256: raise FailClosed("AMENDMENT_D_HASH_DRIFT")
    return _hash64(configured,"AMENDMENT_D_HASH_NOT_PINNED")

def _expected_amendment_hash(amendment_id: str) -> str:
    return {"A": AMENDMENT_A_SHA256, "B": AMENDMENT_B_SHA256,
            "C": AMENDMENT_C_SHA256, "D": _amendment_d_sha256()}[amendment_id]

def _owner_key() -> bytes:
    path = os.environ.get("P5_OWNER_ED25519_PUBLIC_KEY_FILE", "")
    if not path or not Path(path).is_file():
        raise FailClosed("OWNER_PUBLIC_KEY_NOT_CONFIGURED")
    raw = Path(path).read_bytes()
    if len(raw) != 32:
        raise FailClosed("OWNER_PUBLIC_KEY_INVALID")
    return raw

def _owner_uid() -> int:
    return int(os.environ.get("P5_OWNER_PEER_UID", "-1"))

class AuthorityStore:
    def __init__(self, db_path: Path):
        self.db_path = db_path

    def _open(self):
        con = apsw.Connection(str(self.db_path)); con.set_busy_timeout(2000)
        con.execute("PRAGMA foreign_keys=ON")
        return con

    def proposal(self, payload: dict[str, Any], ctx: DaemonContext) -> dict[str, Any]:
        ctx.validate(); bindings = FrozenBindings(**payload["bindings"]).validate()
        proposal_id = str(payload["proposal_id"]); binding_json = canonical_json(vars(bindings))
        resource_hash = resource_policy_sha256(bindings.resource_scope) if bindings.wave_id is not None else None
        con = self._open()
        try:
            con.execute("BEGIN IMMEDIATE")
            con.execute("INSERT INTO authority_proposals(proposal_id,family_id,run_id,run_class,binding_sha256,binding_json,producer_session_id,expires_at,created_at,resource_policy_sha256) VALUES(?,?,?,?,?,?,?,?,?,?)", (proposal_id,bindings.family_id,bindings.run_id,bindings.run_class,bindings.digest,binding_json,ctx.session_id,str(payload["expires_at"]),ctx.recorded_at,resource_hash))
            con.execute("INSERT INTO authority_transitions(proposal_id,from_state,to_state,daemon_recorded_at,daemon_ledger_sequence,immutable_session_id,authenticated_peer_uid,event_sha256,resource_policy_sha256) VALUES(?,?,?,?,?,?,?,?,?)", (proposal_id,"NONE","PROPOSED",ctx.recorded_at,ctx.ledger_sequence,ctx.session_id,ctx.peer_uid,_sha({"p":proposal_id,"to":"PROPOSED","seq":ctx.ledger_sequence}),resource_hash))
            con.execute("COMMIT")
        except BaseException:
            if not con.getautocommit(): con.execute("ROLLBACK")
            raise
        finally: con.close()
        return {"status":"PASS","proposal_id":proposal_id,"state":"PROPOSED","binding_sha256":bindings.digest}

    def transition(self, proposal_id: str, target: str, ctx: DaemonContext, observed_binding_sha256: str|None=None) -> dict[str, Any]:
        ctx.validate(); con = self._open()
        try:
            con.execute("BEGIN IMMEDIATE")
            row = con.execute("SELECT binding_sha256,producer_session_id,expires_at,resource_policy_sha256 FROM authority_proposals WHERE proposal_id=?",(proposal_id,)).fetchone()
            if not row: raise FailClosed("PROPOSAL_NOT_FOUND")
            last = con.execute("SELECT to_state FROM authority_transitions WHERE proposal_id=? ORDER BY transition_id DESC LIMIT 1",(proposal_id,)).fetchone()
            current = last[0]; wanted={"PROPOSED":"PRECONDITIONS_PASS","PRECONDITIONS_PASS":"HUMAN_OWNER_SIGNED","HUMAN_OWNER_SIGNED":"APPLIED"}.get(current)
            if target != wanted: raise FailClosed("ILLEGAL_AUTHORITY_TRANSITION")
            if target == "PRECONDITIONS_PASS" and observed_binding_sha256 != row[0]: raise FailClosed("BINDING_MISMATCH")
            if target == "HUMAN_OWNER_SIGNED":
                if ctx.peer_uid != _owner_uid(): raise FailClosed("OWNER_CREDENTIAL_REQUIRED")
                if ctx.session_id == row[1]: raise FailClosed("OWNER_SESSION_SEPARATION_FAILED")
            if target == "APPLIED" and parse_utc(ctx.recorded_at) >= parse_utc(row[2]):
                raise FailClosed("AUTHORITY_PROPOSAL_EXPIRED")
            con.execute("INSERT INTO authority_transitions(proposal_id,from_state,to_state,daemon_recorded_at,daemon_ledger_sequence,immutable_session_id,authenticated_peer_uid,event_sha256,resource_policy_sha256) VALUES(?,?,?,?,?,?,?,?,?)",(proposal_id,current,target,ctx.recorded_at,ctx.ledger_sequence,ctx.session_id,ctx.peer_uid,_sha({"p":proposal_id,"to":target,"seq":ctx.ledger_sequence}),row[3]))
            con.execute("COMMIT")
        except BaseException:
            if not con.getautocommit(): con.execute("ROLLBACK")
            raise
        finally: con.close()
        return {"status":"PASS","proposal_id":proposal_id,"state":target}

    def register_delegation(self, payload: dict[str, Any], ctx: DaemonContext) -> dict[str, Any]:
        ctx.validate(); delegation=OwnerConditionalDelegation(**payload); verifier=DelegationVerifier(_owner_key()); verifier.verify_signature(delegation)
        if delegation.amendment_a_sha256 != AMENDMENT_A_SHA256 or delegation.amendment_b_sha256 != AMENDMENT_B_SHA256 or delegation.amendment_c_sha256 != AMENDMENT_C_SHA256 or delegation.amendment_d_sha256 != _amendment_d_sha256():
            raise FailClosed("ROOT_AMENDMENT_BINDING_MISMATCH")
        signature=base64.b64decode(delegation.owner_signature,validate=True); resource_hash=resource_policy_sha256(delegation.resource_policy)
        con=self._open()
        try:
            con.execute("BEGIN IMMEDIATE")
            observed=list(con.execute("SELECT amendment_id,amendment_sha256,authorization_mode,state FROM amendment_registrations ORDER BY registration_ordinal"))
            expected=[("C",AMENDMENT_C_SHA256,"INTERACTIVE_OWNER_SIGN","APPLIED"),("D",_amendment_d_sha256(),"INTERACTIVE_OWNER_SIGN","APPLIED")]
            if observed != expected: raise FailClosed("EXACT_C_AND_D_DIRECT_OWNER_APPLIED_REQUIRED")
            con.execute("INSERT INTO owner_conditional_delegations(delegation_id,owner_identity,owner_credential_scheme,unsigned_payload_json,owner_signature_b64,owner_signature_sha256,owner_session_id,expires_at,scope_sha256,state,resource_policy_sha256) VALUES(?,?,?,?,?,?,?,?,?,?,?)",(delegation.delegation_id,delegation.owner_identity,delegation.owner_credential_scheme,canonical_json(delegation.unsigned_payload()),delegation.owner_signature,hashlib.sha256(signature).hexdigest(),delegation.owner_session_id,delegation.expires_at,delegation.scope_hash,"ACTIVE",resource_hash))
            con.execute("COMMIT")
        except BaseException:
            if not con.getautocommit(): con.execute("ROLLBACK")
            raise
        finally: con.close()
        return {"status":"PASS","delegation_id":delegation.delegation_id,"scope_sha256":delegation.scope_hash}

    def redeem(self, delegation_id: str, proposal_payload: dict[str, Any], ctx: DaemonContext) -> dict[str, Any]:
        ctx.validate(); con=self._open()
        try:

            con.execute("BEGIN IMMEDIATE")
            row=con.execute("SELECT unsigned_payload_json,owner_signature_b64 FROM owner_conditional_delegations WHERE delegation_id=?",(delegation_id,)).fetchone()
            if not row: raise FailClosed("DELEGATION_NOT_FOUND")
            raw=json.loads(row[0]); raw["owner_signature"]=row[1]; delegation=OwnerConditionalDelegation(**raw); proposal=ChildProposal(**proposal_payload)
            canonical=con.execute("SELECT producer_session_id,binding_json,resource_policy_sha256 FROM authority_proposals WHERE proposal_id=?",(proposal.proposal_id,)).fetchone()
            if not canonical: raise FailClosed("PROPOSAL_NOT_FOUND")
            proposal=replace(proposal,producer_session_id=canonical[0]); binding=json.loads(canonical[1])
            canonical_pairs=(
                (proposal.family,binding["family_id"]),(proposal.run_class,binding["run_class"]),
                (proposal.evidence_domain,binding["evidence_domain"]),
                (proposal.dataset_manifest_hash,binding["dataset_manifest_sha256"]),
                (proposal.revision_hash,binding["revision_lineage_sha256"]),
                (proposal.pit_rule_hash,binding["universe_rule_sha256"]),
                (proposal.t1_prereg_hash,binding["prereg_sha256"]),
                (proposal.integrity_void_contract_hash,binding["validation_contract_sha256"]),
                (proposal.evaluator_hash,binding["evaluator_sha256"]),
            )
            if proposal.proposal_type=="WAVE1_STATISTICAL_TRIAL":
                canonical_pairs += (
                    (proposal.candidate_list_hash,binding["candidate_list_sha256"]),
                    (proposal.candidate_grammar_hash,binding["candidate_grammar_sha256"]),
                    (proposal.enumerator_hash,binding["enumerator_sha256"]),
                    (proposal.evaluation_order_hash,binding["evaluation_order_sha256"]),
                    (proposal.scientific_contract_hash,binding["executable_contract_sha256"]),
                )
            if not all(left==right for left,right in canonical_pairs):
                raise FailClosed("CANONICAL_PROPOSAL_SCOPE_MISMATCH")
            if proposal.proposal_type=="WAVE1_STATISTICAL_TRIAL" and (proposal.resource_policy is None or resource_policy_sha256(proposal.resource_policy)!=canonical[2]): raise FailClosed("RESOURCE_POLICY_BINDING_MISMATCH")
            pre=con.execute("SELECT transition_id,daemon_ledger_sequence FROM authority_transitions WHERE proposal_id=? AND to_state='PRECONDITIONS_PASS' ORDER BY transition_id DESC LIMIT 1",(proposal.proposal_id,)).fetchone()
            if not pre: raise FailClosed("PRECONDITIONS_PASS_ABSENT")
            if con.execute("SELECT 1 FROM owner_delegation_revocations WHERE delegation_id=?",(delegation_id,)).fetchone(): raise FailClosed("DELEGATION_REVOKED")
            event=DelegationVerifier(_owner_key()).redeem(delegation,proposal,{"to":"PRECONDITIONS_PASS","ledger_sequence":pre[1],"event_id":str(pre[0])},ctx)
            con.execute("INSERT INTO authority_transitions(proposal_id,from_state,to_state,daemon_recorded_at,daemon_ledger_sequence,immutable_session_id,authenticated_peer_uid,event_sha256,resource_policy_sha256) VALUES(?,?,?,?,?,?,?,?,?)",(proposal.proposal_id,"PRECONDITIONS_PASS","HUMAN_OWNER_SIGNED",ctx.recorded_at,ctx.ledger_sequence,ctx.session_id,ctx.peer_uid,_sha(event),event.get("resource_policy_sha256")))
            transition_id=con.last_insert_rowid()
            con.execute("INSERT INTO delegation_redemptions(redemption_event_id,delegation_id,child_proposal_id,preconditions_transition_id,human_owner_signed_transition_id,scope_sha256,resource_policy_sha256) VALUES(?,?,?,?,?,?,?)",(event["redemption_event_id"],delegation_id,proposal.proposal_id,pre[0],transition_id,event["scope_hash"],event.get("resource_policy_sha256")))
            con.execute("COMMIT")
        except BaseException:
            if not con.getautocommit(): con.execute("ROLLBACK")
            raise
        finally: con.close()
        return {"status":"PASS","event":event}

    def revoke(self, delegation_id: str, ctx: DaemonContext) -> dict[str, Any]:
        ctx.validate()
        if ctx.peer_uid != _owner_uid(): raise FailClosed("OWNER_CREDENTIAL_REQUIRED")
        event_id="revoke-"+_sha({"d":delegation_id,"seq":ctx.ledger_sequence})[:32]; con=self._open()
        try: con.execute("INSERT INTO owner_delegation_revocations VALUES(?,?,?,?,?)",(event_id,delegation_id,ctx.recorded_at,ctx.ledger_sequence,ctx.peer_uid))
        finally: con.close()
        return {"status":"PASS","event":"OWNER_DELEGATION_REVOKED","revocation_event_id":event_id}

    def register_amendment(self, delegation_id: str, amendment_id: str, amendment_hash: str, ctx: DaemonContext) -> dict[str, Any]:
        ctx.validate()
        if amendment_id not in {"A","B"}: raise FailClosed("ROOT_CANNOT_REGISTER_C_OR_D")
        con=self._open()
        try:
            con.execute("BEGIN IMMEDIATE")
            row=con.execute("SELECT unsigned_payload_json,owner_signature_b64 FROM owner_conditional_delegations WHERE delegation_id=?",(delegation_id,)).fetchone()
            if not row: raise FailClosed("DELEGATION_NOT_FOUND")
            if con.execute("SELECT 1 FROM owner_delegation_revocations WHERE delegation_id=?",(delegation_id,)).fetchone(): raise FailClosed("DELEGATION_REVOKED")
            raw=json.loads(row[0]); raw["owner_signature"]=row[1]; delegation=OwnerConditionalDelegation(**raw); DelegationVerifier(_owner_key()).verify_signature(delegation)
            observed=[item[0] for item in con.execute("SELECT amendment_id FROM amendment_registrations ORDER BY registration_ordinal")]
            expected=["C","D","A","B"]
            if observed!=expected[:len(observed)] or len(observed)>=4 or amendment_id!=expected[len(observed)]: raise FailClosed("C_D_A_B_ORDER_VIOLATION")
            exact={"A":delegation.amendment_a_sha256,"B":delegation.amendment_b_sha256}
            if amendment_hash!=exact[amendment_id] or amendment_hash!=_expected_amendment_hash(amendment_id): raise FailClosed("AMENDMENT_ID_HASH_BINDING_MISMATCH")
            event_id="amend-"+_sha({"d":delegation_id,"a":amendment_id,"seq":ctx.ledger_sequence})[:32]
            con.execute("INSERT INTO amendment_registrations(amendment_event_id,amendment_id,amendment_sha256,registration_ordinal,authorization_mode,delegation_id,daemon_recorded_at,daemon_ledger_sequence,authenticated_owner_uid,producer_session_id,owner_session_id,state) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",(event_id,amendment_id,amendment_hash,len(observed)+1,"PREAUTHORIZED_CONDITIONAL_DELEGATION",delegation_id,ctx.recorded_at,ctx.ledger_sequence,None,ctx.session_id,delegation.owner_session_id,"APPLIED"))
            con.execute("COMMIT")
        except BaseException:
            if not con.getautocommit(): con.execute("ROLLBACK")
            raise
        finally: con.close()
        return {"status":"PASS","amendment_event_id":event_id,"amendment_id":amendment_id,"registration_ordinal":len(observed)+1,"state":"APPLIED"}

    def register_amendment_direct(self, amendment_id: str, amendment_hash: str, producer_session_id: str, ctx: DaemonContext) -> dict[str, Any]:
        ctx.validate()
        if ctx.peer_uid != _owner_uid(): raise FailClosed("OWNER_CREDENTIAL_REQUIRED")
        if not producer_session_id or producer_session_id==ctx.session_id: raise FailClosed("OWNER_SESSION_SEPARATION_FAILED")
        if amendment_id not in {"C","D"}: raise FailClosed("DIRECT_OWNER_ONLY_C_OR_D")
        if amendment_hash != _expected_amendment_hash(amendment_id): raise FailClosed("AMENDMENT_ID_HASH_BINDING_MISMATCH")
        con=self._open()
        try:
            con.execute("BEGIN IMMEDIATE")
            observed=[row[0] for row in con.execute("SELECT amendment_id FROM amendment_registrations ORDER BY registration_ordinal")]
            expected=["C","D"]
            if observed!=expected[:len(observed)] or len(observed)>=2 or amendment_id!=expected[len(observed)]: raise FailClosed("C_FIRST_D_SECOND_REQUIRED")
            event_id="amend-direct-"+_sha({"a":amendment_id,"h":amendment_hash,"seq":ctx.ledger_sequence})[:32]
            con.execute("INSERT INTO amendment_registrations(amendment_event_id,amendment_id,amendment_sha256,registration_ordinal,authorization_mode,delegation_id,daemon_recorded_at,daemon_ledger_sequence,authenticated_owner_uid,producer_session_id,owner_session_id,state) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",(event_id,amendment_id,amendment_hash,len(observed)+1,"INTERACTIVE_OWNER_SIGN",None,ctx.recorded_at,ctx.ledger_sequence,ctx.peer_uid,producer_session_id,ctx.session_id,"APPLIED"))
            con.execute("COMMIT")
        except BaseException:
            if not con.getautocommit(): con.execute("ROLLBACK")
            raise
        finally: con.close()
        return {"status":"PASS","amendment_event_id":event_id,"amendment_id":amendment_id,"registration_ordinal":len(observed)+1,"state":"APPLIED"}

"""P5 PC7 authority/amendment/trial runtime (engineering layer).

The daemon supplies ``peer_uid``, append-only sequence and canonical time.
Producer timestamps and payload role strings are never authorization inputs.
This module has no Research Memory write path; production persistence is the
separate, audited schema migration.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from datetime import datetime, timezone
import hashlib
import json
from typing import Any, Callable


STATES = ("PROPOSED", "PRECONDITIONS_PASS", "HUMAN_OWNER_SIGNED", "APPLIED")
RUN_CLASSES = {"STATISTICAL_TRIAL", "SYNTHETIC_TEST"}

RESOURCE_POLICY_TYPE = "WAVE1_CUMULATIVE_ACTIVE_WALL_TIME_V1"
RESOURCE_POLICY_KEYS = {
    "policy_type", "wall_time_expiry_seconds", "clock", "starts_at",
    "accumulation", "checkpoint_semantics", "on_exhaustion",
    "scientific_early_stop", "candidate_count", "decision_basis",
}
RESOURCE_DECISION_BASIS_KEYS = {
    "source", "benchmark_sha256", "real_p5_labels_read_before_choice",
}


class AuthorityError(RuntimeError):
    pass


class AuthorizationDenied(AuthorityError):
    pass


class BindingMismatch(AuthorityError):
    pass


def canonical_json(value: Any) -> bytes:
    return json.dumps(value, ensure_ascii=False, sort_keys=True,
                      separators=(",", ":"), allow_nan=False).encode("utf-8")


def sha256(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()


def parse_utc(value: str) -> datetime:
    if not isinstance(value, str) or not value.endswith("Z"):
        raise AuthorityError("daemon time must be RFC3339 UTC")
    parsed = datetime.fromisoformat(value[:-1] + "+00:00")
    if parsed.utcoffset() != timezone.utc.utcoffset(parsed):
        raise AuthorityError("daemon time must be UTC")
    return parsed


def validate_resource_policy(value: Any) -> dict[str, Any]:
    """Validate the owner-late-bound, outcome-blind Wave-1 resource policy.

    Amendment D defines ``wall_time_expiry`` as a cumulative active-attempt
    duration in integer seconds.  It is deliberately distinct from the
    security credential's absolute ``expires_at`` timestamp.  The owner
    chooses the integer after the sealed synthetic benchmark and before the
    first P3 real-label access; this function never supplies a default.
    """
    if not isinstance(value, dict) or set(value) != RESOURCE_POLICY_KEYS:
        raise AuthorityError("RESOURCE_POLICY_EXACT_FIELDS_REQUIRED")
    if value["policy_type"] != RESOURCE_POLICY_TYPE:
        raise AuthorityError("RESOURCE_POLICY_TYPE_INVALID")
    seconds = value["wall_time_expiry_seconds"]
    if isinstance(seconds, bool) or not isinstance(seconds, int) or seconds <= 0:
        raise AuthorityError("RESOURCE_POLICY_SECONDS_INVALID")
    expected = {
        "clock": "DAEMON_MONOTONIC_ACTIVE_ATTEMPT_TIME",
        "starts_at": "WAVE1_APPLIED",
        "accumulation": "SUM_ALL_ATTEMPTS_SAME_LOGICAL_WAVE",

CREATE TABLE authority_proposals (
 proposal_id TEXT PRIMARY KEY,family_id TEXT NOT NULL,run_id TEXT NOT NULL,
 run_class TEXT NOT NULL CHECK(run_class='STATISTICAL_TRIAL'),
 binding_sha256 TEXT NOT NULL CHECK(length(binding_sha256)=64),
 binding_json TEXT NOT NULL CHECK(json_valid(binding_json)),producer_session_id TEXT NOT NULL,
 expires_at TEXT NOT NULL,created_at TEXT NOT NULL,
 resource_policy_sha256 TEXT CHECK(resource_policy_sha256 IS NULL OR length(resource_policy_sha256)=64),
 UNIQUE(run_id,binding_sha256)
) STRICT;
CREATE TABLE authority_transitions (
 transition_id INTEGER PRIMARY KEY AUTOINCREMENT,proposal_id TEXT NOT NULL REFERENCES authority_proposals(proposal_id),
 from_state TEXT NOT NULL CHECK(from_state IN ('NONE','PROPOSED','PRECONDITIONS_PASS','HUMAN_OWNER_SIGNED')),
 to_state TEXT NOT NULL CHECK(to_state IN ('PROPOSED','PRECONDITIONS_PASS','HUMAN_OWNER_SIGNED','APPLIED')),
 daemon_recorded_at TEXT NOT NULL,daemon_ledger_sequence INTEGER NOT NULL,immutable_session_id TEXT NOT NULL,
 authenticated_peer_uid INTEGER NOT NULL,event_sha256 TEXT NOT NULL UNIQUE CHECK(length(event_sha256)=64),
 resource_policy_sha256 TEXT CHECK(resource_policy_sha256 IS NULL OR length(resource_policy_sha256)=64),
 UNIQUE(proposal_id,daemon_ledger_sequence)
) STRICT;
CREATE TABLE logical_trials (logical_trial_id TEXT PRIMARY KEY,grant_proposal_id TEXT NOT NULL REFERENCES authority_proposals(proposal_id),candidate_list_sha256 TEXT NOT NULL CHECK(length(candidate_list_sha256)=64),UNIQUE(grant_proposal_id)) STRICT;
CREATE TABLE trial_attempts (attempt_id TEXT PRIMARY KEY,logical_trial_id TEXT NOT NULL REFERENCES logical_trials(logical_trial_id),attempt_ordinal INTEGER NOT NULL CHECK(attempt_ordinal>=1),state TEXT NOT NULL CHECK(state IN ('RUNNING','ATTEMPT_VOID','COMPLETED')),checkpoint_sha256 TEXT CHECK(checkpoint_sha256 IS NULL OR length(checkpoint_sha256)=64),UNIQUE(logical_trial_id,attempt_ordinal)) STRICT;
CREATE TABLE owner_conditional_delegations (delegation_id TEXT PRIMARY KEY,owner_identity TEXT NOT NULL,owner_credential_scheme TEXT NOT NULL CHECK(owner_credential_scheme='ED25519'),unsigned_payload_json TEXT NOT NULL CHECK(json_valid(unsigned_payload_json)),owner_signature_b64 TEXT NOT NULL,owner_signature_sha256 TEXT NOT NULL CHECK(length(owner_signature_sha256)=64),owner_session_id TEXT NOT NULL,expires_at TEXT NOT NULL,scope_sha256 TEXT NOT NULL CHECK(length(scope_sha256)=64),state TEXT NOT NULL CHECK(state='ACTIVE'),resource_policy_sha256 TEXT NOT NULL CHECK(length(resource_policy_sha256)=64)) STRICT;
CREATE TABLE delegation_redemptions (redemption_event_id TEXT PRIMARY KEY,delegation_id TEXT NOT NULL REFERENCES owner_conditional_delegations(delegation_id),child_proposal_id TEXT NOT NULL REFERENCES authority_proposals(proposal_id),preconditions_transition_id INTEGER NOT NULL REFERENCES authority_transitions(transition_id),human_owner_signed_transition_id INTEGER NOT NULL REFERENCES authority_transitions(transition_id),scope_sha256 TEXT NOT NULL CHECK(length(scope_sha256)=64),resource_policy_sha256 TEXT CHECK(resource_policy_sha256 IS NULL OR length(resource_policy_sha256)=64),UNIQUE(delegation_id,child_proposal_id)) STRICT;
CREATE TABLE owner_delegation_revocations (revocation_event_id TEXT PRIMARY KEY,delegation_id TEXT NOT NULL REFERENCES owner_conditional_delegations(delegation_id),daemon_recorded_at TEXT NOT NULL,daemon_ledger_sequence INTEGER NOT NULL,authenticated_owner_uid INTEGER NOT NULL,UNIQUE(delegation_id)) STRICT;
CREATE TABLE amendment_registrations (amendment_event_id TEXT PRIMARY KEY,amendment_id TEXT NOT NULL CHECK(amendment_id IN ('C','D','A','B')),amendment_sha256 TEXT NOT NULL CHECK(length(amendment_sha256)=64),registration_ordinal INTEGER NOT NULL CHECK(registration_ordinal BETWEEN 1 AND 4),authorization_mode TEXT NOT NULL CHECK(authorization_mode IN ('INTERACTIVE_OWNER_SIGN','PREAUTHORIZED_CONDITIONAL_DELEGATION')),delegation_id TEXT REFERENCES owner_conditional_delegations(delegation_id),daemon_recorded_at TEXT NOT NULL,daemon_ledger_sequence INTEGER NOT NULL UNIQUE,authenticated_owner_uid INTEGER,producer_session_id TEXT NOT NULL,owner_session_id TEXT NOT NULL,state TEXT NOT NULL CHECK(state='APPLIED'),UNIQUE(amendment_id),UNIQUE(registration_ordinal),CHECK(producer_session_id<>owner_session_id),CHECK((authorization_mode='INTERACTIVE_OWNER_SIGN' AND delegation_id IS NULL AND authenticated_owner_uid IS NOT NULL) OR (authorization_mode='PREAUTHORIZED_CONDITIONAL_DELEGATION' AND delegation_id IS NOT NULL AND authenticated_owner_uid IS NULL))) STRICT;

CREATE TRIGGER authority_transition_order BEFORE INSERT ON authority_transitions BEGIN SELECT CASE
 WHEN NEW.daemon_ledger_sequence<=coalesce((SELECT max(daemon_ledger_sequence) FROM authority_transitions WHERE proposal_id=NEW.proposal_id),-1) THEN RAISE(ABORT,'daemon ledger order is not append-only')
 WHEN NEW.to_state='PROPOSED' AND (NEW.from_state!='NONE' OR EXISTS(SELECT 1 FROM authority_transitions WHERE proposal_id=NEW.proposal_id)) THEN RAISE(ABORT,'illegal authority transition')
 WHEN NEW.to_state='PRECONDITIONS_PASS' AND (NEW.from_state!='PROPOSED' OR (SELECT to_state FROM authority_transitions WHERE proposal_id=NEW.proposal_id ORDER BY transition_id DESC LIMIT 1)!='PROPOSED') THEN RAISE(ABORT,'illegal authority transition')
 WHEN NEW.to_state='HUMAN_OWNER_SIGNED' AND (NEW.from_state!='PRECONDITIONS_PASS' OR (SELECT to_state FROM authority_transitions WHERE proposal_id=NEW.proposal_id ORDER BY transition_id DESC LIMIT 1)!='PRECONDITIONS_PASS') THEN RAISE(ABORT,'illegal authority transition')
 WHEN NEW.to_state='APPLIED' AND (NEW.from_state!='HUMAN_OWNER_SIGNED' OR (SELECT to_state FROM authority_transitions WHERE proposal_id=NEW.proposal_id ORDER BY transition_id DESC LIMIT 1)!='HUMAN_OWNER_SIGNED') THEN RAISE(ABORT,'illegal authority transition')
 WHEN NEW.resource_policy_sha256 IS NOT (SELECT resource_policy_sha256 FROM authority_proposals WHERE proposal_id=NEW.proposal_id) THEN RAISE(ABORT,'resource policy transition mismatch') END; END;
CREATE UNIQUE INDEX one_preconditions_per_proposal ON authority_transitions(proposal_id) WHERE to_state='PRECONDITIONS_PASS';
CREATE UNIQUE INDEX one_owner_sign_per_proposal ON authority_transitions(proposal_id) WHERE to_state='HUMAN_OWNER_SIGNED';
CREATE UNIQUE INDEX one_applied_per_proposal ON authority_transitions(proposal_id) WHERE to_state='APPLIED';
CREATE TRIGGER amendment_order_and_identity BEFORE INSERT ON amendment_registrations BEGIN SELECT CASE
 WHEN NEW.daemon_ledger_sequence<=coalesce((SELECT max(daemon_ledger_sequence) FROM amendment_registrations),-1) THEN RAISE(ABORT,'amendment ledger order is not append-only')
 WHEN NEW.registration_ordinal!=coalesce((SELECT max(registration_ordinal)+1 FROM amendment_registrations),1) THEN RAISE(ABORT,'amendment order gap')
 WHEN NEW.registration_ordinal=1 AND NOT(NEW.amendment_id='C' AND NEW.amendment_sha256='5b1d8116aa8ed30b407c4804dae191af34a9e4fcc1b9ec292a73b5eeb7c47c83' AND NEW.authorization_mode='INTERACTIVE_OWNER_SIGN') THEN RAISE(ABORT,'exact direct-owner C required first')
 WHEN NEW.registration_ordinal=2 AND NOT(NEW.amendment_id='D' AND NEW.amendment_sha256='c419cbdc0bc26670d5c18b37f183a9cd3481b00680f0b10d3176e482ef1d5be4' AND NEW.authorization_mode='INTERACTIVE_OWNER_SIGN') THEN RAISE(ABORT,'exact direct-owner D required second')
 WHEN NEW.registration_ordinal=3 AND NOT(NEW.amendment_id='A' AND NEW.amendment_sha256='495ad47fed0210ba4b495bdd86aa28784a5e5594df1e2648b6e04de8aa1fa379' AND NEW.authorization_mode='PREAUTHORIZED_CONDITIONAL_DELEGATION') THEN RAISE(ABORT,'exact delegated A required third')
 WHEN NEW.registration_ordinal=4 AND NOT(NEW.amendment_id='B' AND NEW.amendment_sha256='fa85f7033226c497262418aa1c7bba0eddcb1a340febcf36a5643aa3bddc52bf' AND NEW.authorization_mode='PREAUTHORIZED_CONDITIONAL_DELEGATION') THEN RAISE(ABORT,'exact delegated B required fourth') END; END;
CREATE TRIGGER delegation_requires_exact_cd BEFORE INSERT ON owner_conditional_delegations BEGIN SELECT CASE WHEN (SELECT group_concat(identity,'|') FROM (SELECT amendment_id||':'||amendment_sha256||':'||authorization_mode||':'||state AS identity FROM amendment_registrations ORDER BY registration_ordinal))!='C:5b1d8116aa8ed30b407c4804dae191af34a9e4fcc1b9ec292a73b5eeb7c47c83:INTERACTIVE_OWNER_SIGN:APPLIED|D:c419cbdc0bc26670d5c18b37f183a9cd3481b00680f0b10d3176e482ef1d5be4:INTERACTIVE_OWNER_SIGN:APPLIED' THEN RAISE(ABORT,'exact C and D required before root') END; END;
CREATE TRIGGER redemption_resource_binding BEFORE INSERT ON delegation_redemptions BEGIN SELECT CASE WHEN NEW.scope_sha256!=(SELECT scope_sha256 FROM owner_conditional_delegations WHERE delegation_id=NEW.delegation_id) THEN RAISE(ABORT,'redemption scope mismatch') WHEN NEW.resource_policy_sha256 IS NOT (SELECT resource_policy_sha256 FROM authority_proposals WHERE proposal_id=NEW.child_proposal_id) THEN RAISE(ABORT,'redemption proposal resource mismatch') WHEN NEW.resource_policy_sha256 IS NOT NULL AND NEW.resource_policy_sha256!=(SELECT resource_policy_sha256 FROM owner_conditional_delegations WHERE delegation_id=NEW.delegation_id) THEN RAISE(ABORT,'redemption root resource mismatch') END; END;

